(49,'especialidades','cg1','fichas','[Hematología] Citometría Hemática, Grupo y RH, Plaquetas, VSG, Reticulocitos, Perfil de Hierro,\\n[Química Clínica] QS3, QS7, Perfil Bioquímico 15/24/30/35/45, Glucosa, Creatinina, Colesterol, Triglicéridos,\\n[Electrolitos Séricos] ES 3/4/Completos, Calcio, Fósforo, Magnesio, Bicarbonato CO2,\\n[Uroanálisis] EGO + Radio Prot/Crea, EGO Especializado, Antidoping 5/12 elem.,\\n[Coagulación] Perfil de Coagulación, TP/INR, TTPa, Fibrinógeno, Dímero D, T. Sangrado,\\n[Lípidos] Perfil de Lípidos I, II, Perfil Aterogénico','texto',NULL,'2026-09-17 21:31:17'),
(50,'especialidades','cg1','titulo','Rutina General — Hematología, Química Clínica, Electrolitos, Uroanálisis, Coagulación','texto',NULL,'2026-09-17 21:31:17'),
(51,'especialidades','cg2','fichas','[Función Hepática] PFH Básico, PFH Completo, Transaminasas, GGT, Proteínas Totales, Albumina,\\n[Función Tiroidea] Perfil Tiroideo I-IV, TSH, Ac. Anti Tiroideos I-II, Ac. Anti Receptor TSH, Tiroglobulina,\\n[Función Pancreática] Amilasa sérica, Lipasa sérica,\\n[Función Renal] Cistatina C, Depuración creatinina, Proteínas orina, Microalbuminuria,\\n[Función Cardiaca] Triage cardiaco, Perfil cardiaco completo, Troponina I, Troponina T, NT-pro BNP, Mioglobina,\\n[Gasometría] Gasometría Arterial Completa, Gasometría Venosa Completa','texto',NULL,'2026-09-17 21:31:17'),
(52,'especialidades','cg2','titulo','Función de Órganos — Hepática, Tiroidea, Pancreática, Renal, Cardiaca, Gasometría','texto',NULL,'2026-09-17 21:31:17'),
(53,'especialidades','cg3','fichas','[Hormonas] Perfil Ginecológico I-II, Perfil Hormonal Masculino, FSH, LH, PRL, PROG, TESTOSTERONA Total/Libre, DHEA-S, Cortisol, AMH, PTH-i,\\n[Diabetes] HbA1c, Insulina, HOMA-IR, Péptido C, Prueba de Tolerancia Glucosa, Test O\'Sullivan,\\n[Inmunología] HIV 1/2, V.D.R.L., Reacciones Febriles, Hepatitis A-B-C, Dengue, COVID-19, Coombs, Procalcitonina,\\n[Reumatología] Perfil Reumático, PCR, Factor Reumatoide, CCP, ANA, Anti DNA, Complementos C3/C4,\\n[Diversos] Vitamina D, Inmunoglobulina E, Somatomedina C, Papanicolaou','texto',NULL,'2026-09-17 21:31:17'),
(54,'especialidades','cg3','titulo','Hormonas, Diabetes e Inmunología — Perfil Ginecológico, Masculino, Diabetes, Inmunología, Reumatología','texto',NULL,'2026-09-17 21:31:17'),
(55,'especialidades','cg4','fichas','[Bacteriología] Cultivo de orina MIC, Ex. Faríngeo MIC, Ex. Vaginal MIC, Uretral MIC, Heces MIC, Lesión MIC, Expectoración MIC, Hemocultivo MIC, Cultivo Micológico,\\n[Marcadores Tumorales] PSA Total, PSA Libre, CEA, AFP, CA-125, CA-15-3, CA-19-9, Perfil Tumoral Femenino/Masculino,\\n[Parasitología] Coproparasitoscópico 3 muestras, Coprológico completo/especial, Sangre Oculta, H. Pylori, Calprotectina, Lactoferrina, Clostridium difficile,\\n[Citroquímicos] LCR, Sinovial, Pleural, Ascitis, Diálisis, Bronquial, Pericárdico,\\n[Biología Molecular] PCR VPH, PCR Mycobacterium, PCR Patógenos respiratorios, PCR Meningitis viral, PCR SARS-CoV-2,\\n[Fertilidad] Espermatobioscopia directa','texto',NULL,'2026-09-17 21:31:17'),
(56,'especialidades','cg4','titulo','Bacteriología, Marcadores Tumorales, Parasitología, Citroquímicos, Biología Molecular, Fertilidad','texto',NULL,'2026-09-17 21:31:17'),
